#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

class HugeInt {
private:
    std::string digits; // stores digits in reverse order (least significant first)

public:
    HugeInt(long long val = 0) {
        std::string s = std::to_string(val);
        digits = std::string(s.rbegin(), s.rend());
    }

    HugeInt(const std::string &str) {
        std::string clean = str.empty() ? "0" : str;
        digits = std::string(clean.rbegin(), clean.rend());
    }

    HugeInt operator+(const HugeInt &op2) const {
        HugeInt temp;
        temp.digits.clear();
        int carry = 0;
        size_t maxLen = std::max(digits.size(), op2.digits.size());

        for (size_t i = 0; i < maxLen || carry; ++i) {
            int sum = carry;
            if (i < digits.size()) sum += digits[i] - '0';
            if (i < op2.digits.size()) sum += op2.digits[i] - '0';
            carry = sum / 10;
            temp.digits.push_back(static_cast<char>('0' + (sum % 10)));
        }
        return temp;
    }

    HugeInt operator+(long long op2) const {
        return *this + HugeInt(op2);
    }

    HugeInt operator+(const std::string &op2) const {
        return *this + HugeInt(op2);
    }

    friend std::ostream &operator<<(std::ostream &os, const HugeInt &num) {
        for (auto it = num.digits.rbegin(); it != num.digits.rend(); ++it) {
            os << *it;
        }
        return os;
    }
};

int main() {
    HugeInt n1(7654321);
    HugeInt n2(7891234);
    HugeInt n3("99999999999999999999999999999");
    HugeInt n4("1");
    HugeInt n5;

    std::cout << "n1 is " << n1 << "\nn2 is " << n2
              << "\nn3 is " << n3 << "\nn4 is " << n4
              << "\nn5 is " << n5 << "\n\n";

    n5 = n1 + n2;
    std::cout << n1 << " + " << n2 << " = " << n5 << "\n\n";

    std::cout << n3 << " + " << n4 << "\n= " << (n3 + n4) << "\n\n";

    n5 = n1 + 9;
    std::cout << n1 << " + 9 = " << n5 << "\n\n";

    n5 = n2 + std::string("10000");
    std::cout << n2 << " + 10000 = " << n5 << std::endl;

    return 0;
}

#include <iostream>
#include <numeric>
#include <stdexcept>

class RationalNumber {
private:
    int numerator;
    int denominator;

    void reduce() {
        if (denominator == 0) {
            throw std::invalid_argument("Denominator cannot be zero.");
        }
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
        int common = std::gcd(numerator, denominator);
        numerator /= common;
        denominator /= common;
    }

public:
    RationalNumber(int num = 0, int den = 1) : numerator(num), denominator(den) {
        reduce();
    }

    RationalNumber operator+(const RationalNumber &r) const {
        return RationalNumber(numerator * r.denominator + r.numerator * denominator,
                              denominator * r.denominator);
    }

    RationalNumber operator-(const RationalNumber &r) const {
        return RationalNumber(numerator * r.denominator - r.numerator * denominator,
                              denominator * r.denominator);
    }

    RationalNumber operator*(const RationalNumber &r) const {
        return RationalNumber(numerator * r.numerator, denominator * r.denominator);
    }

    RationalNumber operator/(const RationalNumber &r) const {
        if (r.numerator == 0) {
            throw std::invalid_argument("Division by zero fraction.");
        }
        return RationalNumber(numerator * r.denominator, denominator * r.numerator);
    }

    bool operator==(const RationalNumber &r) const {
        return numerator == r.numerator && denominator == r.denominator;
    }

    bool operator!=(const RationalNumber &r) const {
        return !(*this == r);
    }

    bool operator<(const RationalNumber &r) const {
        return (numerator * r.denominator) < (r.numerator * denominator);
    }

    bool operator<=(const RationalNumber &r) const {
        return !(r < *this);
    }

    bool operator>(const RationalNumber &r) const {
        return r < *this;
    }

    bool operator>=(const RationalNumber &r) const {
        return !(*this < r);
    }

    friend std::ostream &operator<<(std::ostream &os, const RationalNumber &r) {
        if (r.denominator == 1) {
            os << r.numerator;
        } else {
            os << r.numerator << "/" << r.denominator;
        }
        return os;
    }
};

int main() {
    RationalNumber f1(2, 4);   // reduces to 1/2
    RationalNumber f2(3, -9);  // reduces to -1/3

    std::cout << "f1 = " << f1 << "\n";
    std::cout << "f2 = " << f2 << "\n";
    std::cout << "f1 + f2 = " << (f1 + f2) << "\n";
    std::cout << "f1 - f2 = " << (f1 - f2) << "\n";
    std::cout << "f1 * f2 = " << (f1 * f2) << "\n";
    std::cout << "f1 / f2 = " << (f1 / f2) << "\n";

    std::cout << std::boolalpha;
    std::cout << "f1 == f2: " << (f1 == f2) << "\n";
    std::cout << "f1 > f2: " << (f1 > f2) << "\n";

    return 0;
}
